def _safe_eval(node: ast.AST) -> float:
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return float(node.value)
    # py<3.8 曾用 ast.Num；3.14 已无该属性，不可再引用名字
    num_cls = getattr(ast, "Num", None)
    if num_cls is not None and isinstance(node, num_cls):
        return float(node.n)
    if isinstance(node, ast.UnaryOp) and type(node.op) in _BINOPS:
        return _BINOPS[type(node.op)](_safe_eval(node.operand))
    if isinstance(node, ast.BinOp) and type(node.op) in _BINOPS:
        left = _safe_eval(node.left)
        right = _safe_eval(node.right)
        return _BINOPS[type(node.op)](left, right)
    raise ValueError(f'unsupported expr node: {type(node).__name__}')

